typeAlias.declarationTypeText:
Readonly<{
    /** 本页消费的正式数据空间身份。 */
    scenarioId: string;
    /** 页面导航节点及其蓝图场景身份；省略时页面与数据空间同一身份。 */
    navigationId?: string;
    /** 主视图所属的正式模型名称，而非物理来源别名。 */
    modelName: string;
    /** 本页能力树节点类型，不作为数据身份。 */
    componentType: string;
    /** 用于入口及主视图诊断的页面名称。 */
    title: string;
    /** 与主视图同批读取 default 视图的选项模型；任一失败即入口失败，不使用旧候选。 */
    optionModels?: readonly string[];
}>

